import subprocess, random
def probe(seq, opts=[]):
    with open('/tmp/pin.fa','w') as f: f.write('>r\n%s\n' % seq)
    out = subprocess.run(['/tmp/orig_seqtk','telo','-P']+opts+['/tmp/pin.fa'],capture_output=True,text=True)
    P={}; Q={}
    for line in out.stdout.splitlines():
        c=line.split('\t')
        if c[0]=='P': P[int(c[2])]=int(c[3])
        elif c[0]=='Q': Q[int(c[2])]=int(c[3])
    return P,Q,out.stderr.strip()
def rots(m):
    return set(m[i:]+m[:i] for i in range(len(m)))
R_TTAGGG=rots('TTAGGG'); R_CCCTAA=rots('CCCTAA')
random.seed(42)
seqs=['TTAGGGTTAGGT','TTAGGGCTAGGG','ACGTTAGGG','TTAGGGTTAGGG','ACGTACGT','CCCTAACCCTAA','GATCAGTTAGGGTTAGGGGATC']
mot=['TTAGGG','TAGGGT','AGGGTT','GGGTTA','GGTTAG','GTTAGG']
for i in range(15):
    s=''.join(random.choice('ACGT') for _ in range(random.randint(3,10)))
    s+=random.choice(mot)
    s+=''.join(random.choice('ACGT') for _ in range(random.randint(3,10)))
    if random.random()<0.5: s+=random.choice(mot)+''.join(random.choice('ACGT') for _ in range(4))
    seqs.append(s)
data=[]
for s in seqs:
    P,Q,err=probe(s)
    data.append((s,P,Q))
# hypothesis: delta_Q(p) = +1 iff kmer ending at p+off is in SET, else -1; Q(p)=sum_{q=7..p} delta(q)
# test offsets and sets
best=None
for off in range(-6,7):
    for setname,SET in [('rotT',R_TTAGGG),('rotC',R_CCCTAA),('exactT',{'TTAGGG'}),('exactC',{'CCCTAA'}),('rotEither',R_TTAGGG|R_CCCTAA)]:
        ok=True
        for s,P,Q in data:
            n=len(s)
            # delta at q (1-based) determined by 6-mer ending at q+off
            exp=0
            for q in range(1,n+1):
                if q>=7:
                    e=q+off  # 6-mer = positions e-5..e (1-based)
                    if 6<=e<=n:
                        km=s[e-6:e]
                        d=1 if km in SET else -1
                    else:
                        d=None
                    if d is None: ok=False; break
                    exp+=d
                if Q[q]!=exp: ok=False; break
            if not ok: break
        if ok:
            print('MATCH: 6-mer ending at q+(%d), set=%s'%(off,setname))
print('done')
